fields.InputDefinition:
{
  "goal": "Open the 'MJ: AI Prompts' entity grid — type 'AI Prompts' in the LEFT sidebar 'Search entities...' box and click the 'MJ: AI Prompts' node (or navigate to http://localhost:4200/app/data-explorer/Data?entity=MJ:%20AI%20Prompts). Click a prompt row, then click 'Open Full Record'. Verify the AI Prompt record form LOADS SUCCESSFULLY and displays the prompt's details (such as its Name, Status, Type, and/or Description). It must NOT show a 'Failed to load' error and must NOT get stuck on 'Loading record...'. (The prompt's template text may or may not be populated — that is fine; the form loading with the prompt's details is success.) Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "An MJ: AI Prompts record form opened and LOADED successfully (no 'Failed to load' error, not stuck on 'Loading record...')",
    "The form displays the prompt's details such as Name, Status, Type, or Description",
    "No error messages, blank screens, or crash pages"
  ]
}
